import { MakeLogicType, actions, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

const PAGE_REPORTS_TEASER_VISIT_LIMIT = 3

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pageReportsTeaserLogicValues {
    pageReportsVisits: number
    showTeaser: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pageReportsTeaserLogicActions {
    hoverTeaser: () => {
        value: true
    }
    recordPageReportsVisit: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pageReportsTeaserLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        showTeaser: (pageReportsVisits: number) => boolean
    }
}

export type pageReportsTeaserLogicType = MakeLogicType<
    pageReportsTeaserLogicValues,
    pageReportsTeaserLogicActions,
    Record<string, any>,
    pageReportsTeaserLogicMeta
>

export const pageReportsTeaserLogic = kea<pageReportsTeaserLogicType>([
    path(['products', 'webAnalytics', 'pageReports', 'pageReportsTeaserLogic']),
    actions({
        hoverTeaser: true,
        recordPageReportsVisit: true,
    }),
    reducers({
        pageReportsVisits: [
            0,
            { persist: true },
            {
                recordPageReportsVisit: (state) => state + 1,
            },
        ],
    }),
    selectors({
        showTeaser: [
            (s) => [s.pageReportsVisits],
            (pageReportsVisits: number): boolean => pageReportsVisits < PAGE_REPORTS_TEASER_VISIT_LIMIT,
        ],
    }),
    listeners(({ values, cache }) => ({
        hoverTeaser: () => {
            if (cache.hoverTracked) {
                return
            }
            cache.hoverTracked = true
            posthog.capture('web analytics page reports teaser hovered', {
                page_reports_visits: values.pageReportsVisits,
            })
        },
    })),
])
